mapper.select:
select
c1.C_Name as icmLegalPersonCName, c2.C_Name as icmGenerationUnitName, c1.C_Name_History as legalPersonCNameHistory, c2.C_Name_History as generationUnitNameHistory, c1.C_Abbreviation as icmLegalPersonAbbName, c2.C_Abbreviation as icmGenerationAbbName, mn.* from Inv_Control_Manage mn left join SYS_Company c1 on mn.Icm_Legal_Person_Cid=c1.C_Id left join SYS_Company c2 on mn.Icm_Generation_Unit=c2.C_Id
${params.authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Icm_Create_Time desc
